// entities/Player.js
// Player ship: procedural low-poly fighter (hull + swept wings + cockpit + engines),
// PBR materials, input-driven lateral motion with exponential smoothing, fire cooldown.
// Simulation state (x, cooldown, invulnerability) lives here, NOT in the mesh.

import * as THREE from 'three';
import { makeNeon, makeChrome, makeEmitter, PALETTE } from '../../shared/materials/NeonMaterials.js';
import { CONFIG } from '../config.js';

export class Player {
  constructor(scene) {
    this.scene = scene;
    this.x = 0;
    this.vx = 0;
    this.cooldown = 0;
    this.invuln = 0; // seconds of post-hit invulnerability remaining
    this.alive = true;

    this.group = new THREE.Group();
    this.group.position.set(0, CONFIG.player.y, 0);

    // --- Materials (shared across the ship; disposed by Engine scene walk) ---
    this.hullMat = makeChrome(0x1a2030, 0.3);
    this.wingMat = makeNeon({ color: 0x0c1220, emissive: PALETTE.cyan, emissiveIntensity: 0.55, metalness: 0.8, roughness: 0.3 });
    this.cockpitMat = makeEmitter(PALETTE.cyan, 2.6);
    this.engineMat = makeEmitter(PALETTE.magenta, 3.2);

    // --- Hull: extruded triangle (nose up) ---
    const hullShape = new THREE.Shape();
    hullShape.moveTo(0, 0.62);
    hullShape.lineTo(0.30, -0.34);
    hullShape.lineTo(-0.30, -0.34);
    hullShape.closePath();
    const hullGeo = new THREE.ExtrudeGeometry(hullShape, {
      depth: 0.34,
      bevelEnabled: true,
      bevelThickness: 0.06,
      bevelSize: 0.05,
      bevelSegments: 2,
    });
    hullGeo.translate(0, 0, -0.17);
    const hull = new THREE.Mesh(hullGeo, this.hullMat);
    this.group.add(hull);

    // --- Wings: two swept quads ---
    const wingGeo = new THREE.BufferGeometry();
    const wingVerts = new Float32Array([
      // left wing (triangle strip as 2 tris)
      -0.26, -0.10, 0.02,   -1.02, -0.34, 0.10,   -0.26, -0.42, 0.02,
      -0.26, -0.42, 0.02,   -1.02, -0.34, 0.10,   -0.26, -0.52, 0.10,
      // right wing (mirrored)
      0.26, -0.10, 0.02,    1.02, -0.34, 0.10,    0.26, -0.42, 0.02,
      0.26, -0.42, 0.02,    1.02, -0.34, 0.10,    0.26, -0.52, 0.10,
    ]);
    wingGeo.setAttribute('position', new THREE.BufferAttribute(wingVerts, 3));
    wingGeo.computeVertexNormals();
    const wings = new THREE.Mesh(wingGeo, this.wingMat);
    this.group.add(wings);

    // --- Cockpit: emissive capsule ---
    const cockpitGeo = new THREE.CapsuleGeometry(0.10, 0.30, 4, 10);
    const cockpit = new THREE.Mesh(cockpitGeo, this.cockpitMat);
    cockpit.position.set(0, 0.10, 0.16);
    this.group.add(cockpit);

    // --- Engines: two emissive nozzles ---
    const engineGeo = new THREE.CylinderGeometry(0.09, 0.13, 0.22, 10);
    const engineL = new THREE.Mesh(engineGeo, this.engineMat);
    engineL.position.set(-0.18, -0.44, 0.06);
    const engineR = new THREE.Mesh(engineGeo, this.engineMat);
    engineR.position.set(0.18, -0.44, 0.06);
    this.group.add(engineL, engineR);

    // --- Local point light (cyan rim on nearby geometry) ---
    this.light = new THREE.PointLight(PALETTE.cyan, 2.2, 5.0, 1.8);
    this.light.position.set(0, 0.2, 0.4);
    this.group.add(this.light);

    scene.add(this.group);

    // AABB half-extents (world units) for collision
    this.hx = 0.55;
    this.hy = 0.45;
    this.y = CONFIG.player.y;
  }

  /**
   * @param {number} axisX -1..1 from Input
   * @param {number} dt seconds
   */
  update(axisX, dt) {
    // Exponential smoothing toward target velocity (snappy, no teleport).
    const targetV = axisX * CONFIG.player.speed;
    const k = 1 - Math.exp(-dt / CONFIG.player.tau);
    this.vx += (targetV - this.vx) * k;
    this.x += this.vx * dt;
    if (this.x < -CONFIG.player.xMax) { this.x = -CONFIG.player.xMax; this.vx = 0; }
    if (this.x > CONFIG.player.xMax) { this.x = CONFIG.player.xMax; this.vx = 0; }

    this.group.position.x = this.x;

    // Bank into the turn for weight.
    const bank = THREE.MathUtils.clamp(-this.vx / CONFIG.player.speed, -1, 1) * 0.35;
    this.group.rotation.z += (bank - this.group.rotation.z) * Math.min(1, dt * 12);
    this.group.rotation.x = 0;

    // Engine flicker (emissive pulse) — cheap, no allocation.
    const flicker = 2.6 + Math.sin(performance.now() * 0.02) * 0.5;
    this.engineMat.emissiveIntensity = flicker;

    if (this.cooldown > 0) this.cooldown -= dt;
    if (this.invuln > 0) {
      this.invuln -= dt;
      // Blink while invulnerable.
      const on = Math.floor(performance.now() / 90) % 2 === 0;
      this.group.visible = on;
    } else {
      this.group.visible = true;
    }
  }

  canFire() {
    return this.alive && this.cooldown <= 0;
  }

  fire() {
    this.cooldown = CONFIG.player.fireCooldown;
  }

  /** Respawn after a hit: recenter, brief invulnerability. */
  respawn() {
    this.x = 0;
    this.vx = 0;
    this.invuln = CONFIG.player.invulnTime;
    this.group.visible = true;
    this.group.position.x = 0;
  }

  get position() {
    return { x: this.x, y: this.y };
  }

  /** Collision-facing alias (Collision.js reads `player.invulnerable`). */
  get invulnerable() {
    return this.invuln > 0;
  }

  get aabb() {
    return { x: this.x, y: this.y, hx: this.hx, hy: this.hy };
  }
}

// Space_Invaders/main.js
// Composition root. Wires the render adapter (Engine + PostFX), the shared VFX
// stack, the game systems, the HUD, and the game state machine. Owns dispose().
//
// Dependency direction (enforced): main.js → entities/*, systems/*, vfx/*, shared/*
// No other file imports from main.js.

import * as THREE from 'three';
import { createEngine } from '../shared/core/Engine.js';
import { Input } from '../shared/core/Input.js';
import { ObjectPool } from '../shared/core/ObjectPool.js';
import { ParticleManager } from '../shared/core/ParticleManager.js';
import CameraShake from '../shared/core/CameraShake.js';
import HitStop from '../shared/core/HitStop.js';
import Shockwave from '../shared/core/Shockwave.js';
import MotionTrail from '../shared/core/MotionTrail.js';
import { FloatingText } from '../shared/core/FloatingText.js';
import { AudioEngine } from '../shared/core/AudioEngine.js';
import { createPostFX } from '../shared/fx/PostFX.js';
import { GlassHUD } from '../shared/ui/GlassHUD.js';

import { CONFIG, PALETTE } from './config.js';
import { Player } from './entities/Player.js';
import { PlayerBullet } from './entities/PlayerBullet.js';
import { InvaderBullet } from './entities/InvaderBullet.js';
import { UFO } from './entities/UFO.js';
import { Shield } from './entities/Shield.js';
import { disposeSharedSpecies } from './entities/Invader.js';

import { Formation } from './systems/Formation.js';
import { Spawner } from './systems/Spawner.js';
import { Collision } from './systems/Collision.js';
import { Scoring } from './systems/Scoring.js';
import { WaveManager } from './systems/WaveManager.js';

import { VFXDirector } from './vfx/VFXDirector.js';
import { Starfield } from './vfx/Starfield.js';

// ── Boot ──────────────────────────────────────────────────────────────────

const canvas = document.getElementById('game');
const hud = new GlassHUD(document.body, { title: 'SPACE INVADERS' });

// Render adapter + mandatory bloom stack.
const engine = createEngine(canvas, {
  clearColor: PALETTE.deepSpace,
  onFrame: (dt, elapsed) => update(dt, elapsed),
});
const postFX = createPostFX(engine.renderer, engine.scene, engine.camera, {
  strength: 1.15,
  radius: 0.6,
  threshold: 0.12,
});
// Route the engine's per-frame render through the composer (bloom).
engine.setRender(() => postFX.render());
engine.onResize = (w, h) => postFX.resize(w, h);

// Lighting (PBR-correct; bloom carries the neon weight).
{
  const scene = engine.scene;
  scene.add(new THREE.AmbientLight(0x223055, 0.7));
  const key = new THREE.DirectionalLight(0x8899ff, 0.9);
  key.position.set(5, 8, 6);
  scene.add(key);
  const rim = new THREE.DirectionalLight(0xff2bd6, 0.35);
  rim.position.set(-6, -4, 3);
  scene.add(rim);
}

// Shared VFX stack.
const particles = new ParticleManager(engine.scene, { cap: CONFIG.PARTICLE_CAP });
const shake = new CameraShake({ maxOffset: CONFIG.SHAKE_MAX_OFFSET, decay: CONFIG.SHAKE_DECAY });
const hitStop = new HitStop();
const shockwave = new Shockwave(engine.scene);
const floatingText = new FloatingText(engine.scene);
const audio = new AudioEngine();

// Game entities + systems.
const starfield = new Starfield(engine.scene);
const player = new Player(engine.scene);
const waveManager = new WaveManager();
const formation = new Formation(engine.scene);
formation.waveManager = waveManager;
const ufo = new UFO(engine.scene);
const shield = new Shield(engine.scene);

// Projectile pools (declared before the Spawner that consumes them).
const playerBullets = new ObjectPool(() => new PlayerBullet(engine.scene), 2);
const invaderBullets = new ObjectPool(() => new InvaderBullet(engine.scene), 8);

const spawner = new Spawner(formation, invaderBullets, ufo, audio, waveManager);
const collision = new Collision();
const scoring = new Scoring();

// Motion trails: one for the (single) active player bullet, one for the UFO.
const bulletTrail = new MotionTrail(null, PALETTE.playerBullet, 18);
const ufoTrail = new MotionTrail(ufo.group, PALETTE.ufo, 22);
bulletTrail.addTo(engine.scene);
ufoTrail.addTo(engine.scene);

const vfx = new VFXDirector({ particles, shockwave, floatingText, shake, hitStop, audio });

// ── State ─────────────────────────────────────────────────────────────────

const input = new Input();
let state = 'menu'; // 'menu' | 'playing' | 'paused' | 'gameover'
let lives = CONFIG.START_LIVES;

function resetGame() {
  lives = CONFIG.START_LIVES;
  scoring.reset();
  waveManager.reset();
  formation.reset(waveManager.wave);
  shield.reset();
  ufo.active = false;
  ufo.group.visible = false;
  playerBullets.releaseAll();
  invaderBullets.releaseAll();
  player.respawn();
  spawner.reset();
  bulletTrail.reset();
  ufoTrail.reset();
  hud.setScore(0);
  hud.setBest(scoring.best);
  hud.setWave(1);
  hud.setLives(lives);
  hud.setCombo(1);
}

function startGame() {
  audio.ensure();
  audio.play('start');
  resetGame();
  state = 'playing';
  hud.hideOverlay();
  hud.prompt('DEFEND THE LINE', 1800);
}

function endGame() {
  state = 'gameover';
  scoring.saveBest();
  vfx.gameOver();
  hud.setBest(scoring.best);
  const record = scoring.isRecord() ? ' · NEW RECORD' : '';
  hud.showOverlay(
    'GAME OVER',
    `Final score ${scoring.score}${record}`,
    'Play Again',
    startGame
  );
}

function togglePause() {
  if (state === 'playing') {
    state = 'paused';
    hud.showOverlay('PAUSED', 'Press Esc to resume', 'Resume', () => {
      state = 'playing';
      hud.hideOverlay();
    });
  } else if (state === 'paused') {
    state = 'playing';
    hud.hideOverlay();
  }
}

// ── Update ────────────────────────────────────────────────────────────────

function update(rawDt, elapsed) {
  input.update();

  // Pause / menu / game-over: keep the world rendered + starfield alive, but
  // freeze simulation.
  if (input.consumePause() && (state === 'playing' || state === 'paused')) {
    togglePause();
  }

  if (state !== 'playing') {
    starfield.update(rawDt, elapsed);
    shake.update(rawDt);
    shake.apply(engine.camera);
    return;
  }

  // 1. Hit-stop: dilate the whole world's dt for heavy impacts.
  const dt = hitStop.scale(rawDt);

  // 2. Player.
  player.update(input.axisX, dt);
  if (input.consumeFire() && player.canFire()) {
    const b = playerBullets.acquire();
    if (b) {
      b.spawn(player.x, player.y + 0.6, CONFIG.PLAYER_BULLET_SPEED);
      audio.play('laser');
      // Muzzle flash.
      particles.burst({
        origin: new THREE.Vector3(player.x, player.y + 0.6, 0),
        count: 6, velocity: 2.0, spread: 0.8,
        color: PALETTE.playerBullet, size: 0.6, life: 0.25,
        gravity: 0, drag: 2.0,
      });
    }
  }

  // 3. Formation + spawner.
  formation.update(dt, elapsed);
  spawner.update(dt);

  // 4. Bullets (forEachActive snapshots so release() during iteration is safe).
  playerBullets.forEachActive((b) => {
    if (b.update(dt, CONFIG.bounds.top)) playerBullets.release(b);
  });
  invaderBullets.forEachActive((b) => {
    if (!b.active) { invaderBullets.release(b); return; }
    b.update(dt);
    if (!b.active) invaderBullets.release(b);
  });

  // 5. UFO + trails.
  ufo.update(dt);
  if (ufo.active) ufoTrail.update();
  else ufoTrail.reset();
  const activePB = playerBullets._active.find((b) => b.active);
  if (activePB) {
    bulletTrail.target = activePB.group;
    bulletTrail.update();
  } else {
    bulletTrail.reset();
  }

  // 6. Collisions.
  const pbList = playerBullets._active;
  const ibList = invaderBullets._active;

  // Player bullets vs invaders.
  for (const h of collision.playerBulletsVsInvaders(pbList, formation.invaders)) {
    const info = formation.kill(h.invader);
    if (!info) continue;
    const awarded = scoring.addKill(info.value);
    vfx.invaderKilled(h.point, info.species);
    vfx.scoreText(h.point, '+' + awarded);
    playerBullets.release(h.bullet);
  }

  // Player bullets vs UFO.
  for (const h of collision.playerBulletsVsUfo(pbList, ufo)) {
    const pts = scoring.addUfo(ufo.value);
    vfx.ufoKilled(h.point, pts);
    audio.stopUfoLoop();
    ufo.active = false;
    ufo.group.visible = false;
    playerBullets.release(h.bullet);
  }

  // Invader bullets vs player.
  for (const h of collision.invaderBulletsVsPlayer(ibList, player)) {
    invaderBullets.release(h.bullet);
    lives--;
    scoring.resetCombo();
    vfx.playerHit(h.point);
    hud.setLives(lives);
    hud.setCombo(scoring.multiplier);
    if (lives <= 0) {
      endGame();
      return;
    }
    player.respawn();
  }

  // Invader bullets vs shields.
  for (const h of collision.invaderBulletsVsShields(ibList, shield.bunkers)) {
    const pos = h.shield.erodeAt(h.blockIndex);
    vfx.shieldHit(new THREE.Vector3(pos.x, pos.y, 0));
    invaderBullets.release(h.bullet);
  }

  // Invaders vs shields (formation descends into the bunkers).
  for (const h of collision.invadersVsShields(formation.invaders, shield.bunkers)) {
    h.shield.erodeAt(h.blockIndex);
  }

  // Invasion: formation reached the ship line.
  if (formation.hasInvaded(player.y)) {
    endGame();
    return;
  }

  // 7. Wave clear.
  if (formation.isCleared) {
    vfx.waveClear();
    waveManager.advance();
    formation.reset(waveManager.wave);
    shield.reset();
    hud.setWave(waveManager.wave);
    hud.prompt('WAVE ' + waveManager.wave, 1600);
  }

  // 8. VFX integration + camera shake.
  vfx.update(dt);
  starfield.update(dt, elapsed);
  shake.update(dt);
  shake.apply(engine.camera);

  // 9. HUD.
  hud.setScore(scoring.score);
  hud.setCombo(scoring.multiplier);
}

// ── Boot overlay ──────────────────────────────────────────────────────────

resetGame();
hud.showOverlay(
  'SPACE INVADERS',
  'WASD / Arrows to move · Space / Z to fire · Gamepad supported',
  'Start',
  startGame
);

// ── Teardown (strict memory management) ───────────────────────────────────

function dispose() {
  input.dispose();
  vfx.fx.particles.dispose();
  vfx.fx.shockwave.dispose();
  vfx.fx.floatingText.dispose();
  bulletTrail.dispose();
  ufoTrail.dispose();
  starfield.dispose();
  playerBullets.dispose();
  invaderBullets.dispose();
  formation.dispose();
  shield.dispose();
  ufo.dispose();
  disposeSharedSpecies();
  audio.dispose();
  postFX.dispose();
  hud.dispose();
  engine.dispose();
}

window.addEventListener('beforeunload', dispose, { once: true });
window.__spaceInvadersDispose = dispose;

// shared/core/Engine.js
// Renderer + scene + camera + fixed-timestep loop + full dispose().
// Simulation state lives outside Three.js objects; this is the render adapter.

import * as THREE from 'three';

export function createEngine(canvas, opts = {}) {
  const {
    clearColor = 0x05060f,
    antialias = true,
    pixelRatioCap = 2,
    onFrame = null, // (dt, elapsed) => void, called with effective (hit-stop scaled) dt
    onResize = null,
    render = null    // (renderer, scene, camera) => void; if set, used INSTEAD of renderer.render()
  } = opts;
  let renderFn = render; // mutable via setRender()

  const renderer = new THREE.WebGLRenderer({ canvas, antialias, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, pixelRatioCap));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.setClearColor(clearColor, 1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.1;
  renderer.outputColorSpace = THREE.SRGBColorSpace;

  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(clearColor, 0.012);

  const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 200);
  camera.position.set(0, 0, 14);
  camera.lookAt(0, 0, 0);

  // --- Fixed-timestep loop with hit-stop timescale hook -------------------
  let timescale = 1;
  let running = true;
  let rafId = 0;
  let last = performance.now();
  let elapsed = 0;

  function frame(now) {
    if (!running) return;
    rafId = requestAnimationFrame(frame);
    let dt = (now - last) / 1000;
    last = now;
    if (dt > 0.1) dt = 0.1; // tab-switch clamp
    const effectiveDt = dt * timescale;
    elapsed += effectiveDt;
    if (onFrame) onFrame(effectiveDt, elapsed);
    if (renderFn) renderFn(renderer, scene, camera);
    else renderer.render(scene, camera);
  }
  rafId = requestAnimationFrame(frame);

  // --- Resize ---------------------------------------------------------------
  function resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    if (onResize) onResize(w, h);
  }
  window.addEventListener('resize', resize);

  // --- Context loss safety ---------------------------------------------------
  const onContextLost = (e) => { e.preventDefault(); running = false; };
  const onContextRestored = () => { last = performance.now(); running = true; rafId = requestAnimationFrame(frame); };
  canvas.addEventListener('webglcontextlost', onContextLost);
  canvas.addEventListener('webglcontextrestored', onContextRestored);

  // --- Full dispose: walk scene graph, free every GPU resource ---------------
  function dispose() {
    running = false;
    cancelAnimationFrame(rafId);
    window.removeEventListener('resize', resize);
    canvas.removeEventListener('webglcontextlost', onContextLost);
    canvas.removeEventListener('webglcontextrestored', onContextRestored);

    const seen = new Set();
    scene.traverse((obj) => {
      if (seen.has(obj)) return;
      seen.add(obj);
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          for (const key of Object.keys(m)) {
            const v = m[key];
            if (v && v.isTexture) v.dispose();
          }
          m.dispose();
        }
      }
    });
    scene.clear();
    renderer.dispose();
  }

  return {
    renderer,
    scene,
    camera,
    resize,
    dispose,
    setTimescale: (t) => { timescale = t; },
    getTimescale: () => timescale,
    setRender: (fn) => { renderFn = fn; },
    get elapsed() { return elapsed; }
  };
}

