export class GlassHUD {
  /**
   * @param {HTMLElement} container - element to attach the HUD into (usually document.body)
   * @param {object} [opts]
   * @param {string} [opts.title] - overlay title text
   */
  constructor(container, opts = {}) {
    this.container = container;
    this.title = opts.title || 'SPACE INVADERS';

    this.root = document.createElement('div');
    this.root.className = 'glass-hud';

    const style = document.createElement('style');
    style.textContent = BASE_CSS;
    this.root.appendChild(style);

    // Left cluster: score + high score
    this.left = document.createElement('div');
    this.left.className = 'glass-panel hud-left';
    this.left.innerHTML = `
      <div><span class="label">Score</span> <span class="value" id="hud-score">0</span></div>
      <div><span class="label">Best</span> <span class="value" id="hud-best" style="font-size:15px;opacity:.85">0</span></div>
    `;
    this.root.appendChild(this.left);

    // Right cluster: wave + lives + combo
    this.right = document.createElement('div');
    this.right.className = 'glass-panel hud-right';
    this.right.innerHTML = `
      <div><span class="label">Wave</span> <span class="value" id="hud-wave">1</span></div>
      <div class="lives" id="hud-lives"></div>
      <div class="combo" id="hud-combo">×1.0</div>
    `;
    this.root.appendChild(this.right);

    // Center: transient prompt
    this.center = document.createElement('div');
    this.center.className = 'glass-panel hud-center';
    this.center.innerHTML = `<span class="prompt" id="hud-prompt"></span>`;
    this.root.appendChild(this.center);

    // Full-screen overlay (start / game over / pause)
    this.overlay = document.createElement('div');
    this.overlay.className = 'overlay-screen hidden';
    this.overlay.innerHTML = `
      <h1 id="hud-overlay-title">${this.title}</h1>
      <p id="hud-overlay-sub">WASD / Arrows to move · Space / Z to fire · Gamepad supported</p>
      <button class="btn" id="hud-overlay-btn">Start</button>
    `;
    this.root.appendChild(this.overlay);

    this.el = {
      score: this.left.querySelector('#hud-score'),
      best: this.left.querySelector('#hud-best'),
      wave: this.right.querySelector('#hud-wave'),
      lives: this.right.querySelector('#hud-lives'),
      combo: this.right.querySelector('#hud-combo'),
      prompt: this.center.querySelector('#hud-prompt'),
      overlay: this.overlay,
      overlayTitle: this.overlay.querySelector('#hud-overlay-title'),
      overlaySub: this.overlay.querySelector('#hud-overlay-sub'),
      overlayBtn: this.overlay.querySelector('#hud-overlay-btn')
    };

    container.appendChild(this.root);
    this._promptTimer = 0;
  }

  setScore(v) { this.el.score.textContent = String(v); }
  setBest(v) { this.el.best.textContent = String(v); }
  setWave(v) { this.el.wave.textContent = String(v); }

  setLives(n) {
    this.el.lives.innerHTML = '';
    for (let i = 0; i < n; i++) {
      const s = document.createElement('span');
      s.className = 'life-icon';
      this.el.lives.appendChild(s);
    }
  }

  setCombo(mult) {
    if (mult > 1.0) {
      this.el.combo.textContent = '×' + mult.toFixed(1);
      this.el.combo.classList.add('active');
    } else {
      this.el.combo.classList.remove('active');
    }
  }

  /** Show a transient prompt for `ms` milliseconds. */
  prompt(text, ms = 2200) {
    this.el.prompt.textContent = text;
    clearTimeout(this._promptTimer);
    if (ms > 0) {
      this._promptTimer = setTimeout(() => { this.el.prompt.textContent = ''; }, ms);
    }
  }

  showOverlay(title, sub, btnLabel, onBtn) {
    this.el.overlayTitle.textContent = title;
    this.el.overlaySub.textContent = sub;
    this.el.overlayBtn.textContent = btnLabel;
    this.el.overlay.classList.remove('hidden');
    this.el.overlayBtn.onclick = onBtn;
  }

  hideOverlay() { this.el.overlay.classList.add('hidden'); }

  dispose() {
    clearTimeout(this._promptTimer);
    if (this.root.parentNode) this.root.parentNode.removeChild(this.root);
  }
}

/**
 * NeonMaterials.js — PBR MeshStandardMaterial factory + presets.
 * Strict PBR: every material is a MeshStandardMaterial.
 * Emissive intensity is tuned so UnrealBloomPass picks up the glow
 * (threshold ~0.15) while diffuse stays clean.
 */
import * as THREE from 'three';

/**
 * Create a neon PBR material.
 * @param {object} opts
 * @param {number|string} [opts.color]      base albedo (default 0x0a0a14)
 * @param {number|string} [opts.emissive]   emissive color (default = color)
 * @param {number}      [opts.emissiveIntensity=1.5]
 * @param {number}      [opts.metalness=0.85]
 * @param {number}      [opts.roughness=0.25]
 * @param {number}      [opts.opacity=1]
 * @param {boolean}     [opts.transparent=false]
 * @param {number}      [opts.side=THREE.FrontSide]
 */
export function makeNeon(opts = {}) {
  const color = opts.color !== undefined ? opts.color : 0x0a0a14;
  const emissive = opts.emissive !== undefined ? opts.emissive : color;
  const mat = new THREE.MeshStandardMaterial({
    color,
    emissive,
    emissiveIntensity: opts.emissiveIntensity !== undefined ? opts.emissiveIntensity : 1.5,
    metalness: opts.metalness !== undefined ? opts.metalness : 0.85,
    roughness: opts.roughness !== undefined ? opts.roughness : 0.25,
    transparent: opts.transparent === true,
    opacity: opts.opacity !== undefined ? opts.opacity : 1,
    side: opts.side !== undefined ? opts.side : THREE.FrontSide,
  });
  return mat;
}

/**
 * Pure-emitter material: near-black albedo, strong emissive.
 * These are the surfaces that bloom.
 */
export function makeEmitter(color, intensity = 2.2) {
  return makeNeon({
    color: 0x050508,
    emissive: color,
    emissiveIntensity: intensity,
    metalness: 0.4,
    roughness: 0.4,
  });
}

/**
 * Dark chrome — hulls, structural parts.
 */
export function makeChrome(color = 0x14161f, roughness = 0.35) {
  return makeNeon({
    color,
    emissive: 0x000000,
    emissiveIntensity: 0,
    metalness: 0.95,
    roughness,
  });
}

/**
 * Preset palette — AAA retro-futurism neon.
 */
export const PALETTE = {
  cyan:      0x00f0ff,
  magenta:   0xff2bd6,
  violet:    0x8b5cff,
  green:     0x39ff8e,
  amber:     0xffb347,
  red:       0xff3b5c,
  white:     0xeaf6ff,
  deepSpace: 0x05060f,
  grid:      0x1b2a5a,
};

/**
 * Dispose a material and any textures it references.
 */
export function disposeMaterial(mat) {
  if (!mat) return;
  const slots = ['map', 'emissiveMap', 'normalMap', 'roughnessMap', 'metalnessMap', 'aoMap', 'alphaMap'];
  for (const s of slots) {
    if (mat[s] && mat[s].dispose) mat[s].dispose();
  }
  mat.dispose();
}

// shared/core/ParticleManager.js
// Centralized particle system. HARD CAP of 500 active particles.
// One InstancedMesh -> one draw call for the entire particle field.
// CPU-integrated (position/velocity/life per instance), zero per-frame allocation.

import * as THREE from 'three';

const HARD_CAP = 500;

export class ParticleManager {
  constructor(scene, { cap = HARD_CAP, size = 0.09, gravity = -9.0 } = {}) {
    this.scene = scene;
    this.cap = Math.min(cap, HARD_CAP);
    this.gravity = gravity;

    this.count = 0; // active particles

    // Per-instance CPU state (flat arrays, no GC)
    this.pos = new Float32Array(this.cap * 3);
    this.vel = new Float32Array(this.cap * 3);
    this.life = new Float32Array(this.cap);
    this.maxLife = new Float32Array(this.cap);
    this.size = new Float32Array(this.cap);
    this.drag = new Float32Array(this.cap);
    this.color = new Float32Array(this.cap * 3);
    this.active = new Uint8Array(this.cap);
    this.__grav = new Float32Array(this.cap);

    // Geometry: unit quad (billboarded via instance matrix orientation each frame)
    this.geometry = new THREE.PlaneGeometry(1, 1);
    this.material = new THREE.MeshBasicMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });

    this.mesh = new THREE.InstancedMesh(this.geometry, this.material, this.cap);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 20;
    this.mesh.count = 0;
    scene.add(this.mesh);

    this._matrix = new THREE.Matrix4();
    this._quat = new THREE.Quaternion();
    this._scale = new THREE.Vector3();
    this._posV = new THREE.Vector3();
    this._colorObj = new THREE.Color();
    this._burstColor = new THREE.Color();
    this._up = new THREE.Vector3(0, 1, 0);
    this._cursor = 0;
  }

  // Spawn a burst. Returns the number actually spawned (may be < count if cap reached).
  burst({
    origin,
    count = 20,
    velocity = 0,
    spread = 1.0,
    direction = null, // optional THREE.Vector3 bias
    color = 0xffffff,
    colorVariance = 0.15,
    size = 1.0,
    life = 0.8,
    lifeVariance = 0.3,
    gravity = null,
    drag = 1.5,
  }) {
    const col = this._burstColor.set(color);
    let spawned = 0;
    for (let i = 0; i < count; i++) {
      const idx = this._findSlot();
      if (idx < 0) break;
      const i3 = idx * 3;

      // Random direction on sphere, biased by `direction` if given
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      let dx = Math.sin(phi) * Math.cos(theta);
      let dy = Math.sin(phi) * Math.sin(theta);
      let dz = Math.cos(phi);
      if (direction) {
        dx = dx * 0.35 + direction.x * 0.65;
        dy = dy * 0.35 + direction.y * 0.65;
        dz = dz * 0.35 + direction.z * 0.65;
        const len = Math.hypot(dx, dy, dz) || 1;
        dx /= len; dy /= len; dz /= len;
      }

      const speed = velocity * (0.4 + Math.random() * spread);
      this.pos[i3] = origin.x;
      this.pos[i3 + 1] = origin.y;
      this.pos[i3 + 2] = origin.z;
      this.vel[i3] = dx * speed;
      this.vel[i3 + 1] = dy * speed;
      this.vel[i3 + 2] = dz * speed;

      const l = life * (1 - lifeVariance * Math.random());
      this.life[idx] = l;
      this.maxLife[idx] = l;
      this.size[idx] = size * (0.6 + Math.random() * 0.8);
      this.drag[idx] = drag;
      this._grav[idx] = gravity !== null ? gravity : this.gravity;

      const v = colorVariance * (Math.random() - 0.5);
      this.color[i3] = Math.max(0, col.r + v);
      this.color[i3 + 1] = Math.max(0, col.g + v);
      this.color[i3 + 2] = Math.max(0, col.b + v);
      this.active[idx] = 1;
      spawned++;
    }
    return spawned;
  }

  _findSlot() {
    // Rotating cursor: prefer the next dead slot; if the field is full,
    // recycle the oldest (lowest remaining life) so the cap is never exceeded.
    for (let n = 0; n < this.cap; n++) {
      const i = (this._cursor + n) % this.cap;
      if (!this.active[i]) {
        this._cursor = (i + 1) % this.cap;
        return i;
      }
    }
    let oldest = 0;
    let oldestLife = Infinity;
    for (let i = 0; i < this.cap; i++) {
      if (this.life[i] < oldestLife) {
        oldestLife = this.life[i];
        oldest = i;
      }
    }
    this._cursor = (oldest + 1) % this.cap;
    return oldest;
  }

  update(dt) {
    if (this.count === 0 && !this._anyActive()) {
      this.mesh.count = 0;
      return;
    }
    let live = 0;
    for (let i = 0; i < this.cap; i++) {
      if (!this.active[i]) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.active[i] = 0;
        continue;
      }
      const i3 = i * 3;
      // Integrate
      const dragF = Math.max(0, 1 - this.drag[i] * dt);
      this.vel[i3] *= dragF;
      this.vel[i3 + 1] = this.vel[i3 + 1] * dragF + (this._grav ? this._grav[i] : this.gravity) * dt;
      this.vel[i3 + 2] *= dragF;
      this.pos[i3] += this.vel[i3] * dt;
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt;
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt;

      // Write instance matrix (billboard: face +Z toward camera by identity rotation is fine
      // for a plane quad viewed from the front; scale by life fraction)
      const t = this.life[i] / this.maxLife[i];
      const s = this.size[i] * (0.3 + 0.7 * t);
      this._posV.set(this.pos[i3], this.pos[i3 + 1], this.pos[i3 + 2]);
      this._scale.set(s, s, s);
      this._matrix.compose(this._posV, this._quat, this._scale);
      this.mesh.setMatrixAt(live, this._matrix);

      // Color fades out with life
      const fade = t < 0.4 ? t / 0.4 : 1.0;
      this._colorObj.setRGB(
        this.color[i3] * fade,
        this.color[i3 + 1] * fade,
        this.color[i3 + 2] * fade
      );
      this.mesh.setColorAt(live, this._colorObj);
      live++;
    }
    this.count = live;
    this.mesh.count = live;
    if (live > 0) {
      this.mesh.instanceMatrix.needsUpdate = true;
      if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
    }
  }

  _anyActive() {
    for (let i = 0; i < this.cap; i++) if (this.active[i]) return true;
    return false;
  }

  // Initialize the per-instance gravity array lazily (avoids a large allocation in ctor path
  // that some bundlers tree-shake oddly).
  get _grav() {
    if (!this.__grav) this.__grav = new Float32Array(this.cap);
    return this.__grav;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.geometry.dispose();
    this.material.dispose();
    this.mesh.dispose();
  }
}

/**
 * CameraShake — trauma-based camera shake.
 *
 * trauma ∈ [0, 1]. Amplitude scales with trauma² (quadratic falloff reads as
 * "impact weight"). Direction is a smooth pseudo-noise (sum of incommensurate
 * sines) so the shake never looks like a pure jitter.
 *
 * Usage:
 *   const shake = new CameraShake({ maxOffset: 0.35, decay: 1.6 });
 *   shake.addTrauma(0.3);            // on impact
 *   shake.update(dt);                // each frame
 *   shake.apply(camera);             // after update, before render
 */
export default class CameraShake {
  constructor({ maxOffset = 0.35, decay = 1.6 } = {}) {
    this.maxOffset = maxOffset;
    this.decay = decay;
    this.trauma = 0;
    this.time = 0;
    this._basePos = new Float32Array(3);
    this._baseQuat = new Float32Array(4);
  }

  addTrauma(amount) {
    this.trauma = Math.min(1, this.trauma + amount);
  }

  get active() {
    return this.trauma > 0.0005;
  }

  update(dt) {
    if (this.trauma <= 0) return;
    this.time += dt;
    // Linear-ish decay with a soft knee so the tail settles naturally.
    this.trauma = Math.max(0, this.trauma - this.decay * dt * (0.4 + 0.6 * this.trauma));
  }

  /**
   * Apply the shake offset to the camera. Call once per frame after update().
   * The camera's base transform is captured on first apply (or after reset()),
   * so the shake is always relative to where the game put the camera.
   */
  apply(camera) {
    if (!this.active) {
      // Ensure a clean state if we just settled.
      if (this._applied) {
        camera.position.fromArray(this._basePos);
        camera.quaternion.fromArray(this._baseQuat);
        this._applied = false;
      }
      return;
    }
    if (!this._applied) {
      this._basePos.set([camera.position.x, camera.position.y, camera.position.z]);
      this._baseQuat.set([camera.quaternion.x, camera.quaternion.y, camera.quaternion.z, camera.quaternion.w]);
      this._applied = true;
    }
    const t = this.time;
    const amp = this.maxOffset * this.trauma * this.trauma;
    // Smooth pseudo-noise: three incommensurate frequencies per axis.
    const nx = Math.sin(t * 31.7) * 0.6 + Math.sin(t * 17.3 + 1.7) * 0.4;
    const ny = Math.sin(t * 27.1 + 0.9) * 0.6 + Math.sin(t * 13.9 + 4.2) * 0.4;
    const nz = Math.sin(t * 23.3 + 2.1) * 0.5 + Math.sin(t * 11.1 + 3.3) * 0.5;
    camera.position.set(
      this._basePos[0] + nx * amp,
      this._basePos[1] + ny * amp,
      this._basePos[2] + nz * amp * 0.5
    );
    // Tiny rotational wobble for weight.
    const r = amp * 0.05;
    camera.quaternion.set(
      this._baseQuat[0] + Math.sin(t * 19.7) * r,
      this._baseQuat[1] + Math.sin(t * 21.3 + 1.1) * r,
      this._baseQuat[2] + Math.sin(t * 15.9 + 2.3) * r,
      this._baseQuat[3]
    );
  }

  reset() {
    this.trauma = 0;
    this.time = 0;
    this._applied = false;
  }
}

/**
 * HitStop — global timescale dilation (frame-freeze) on heavy impacts.
 *
 * While active, the engine loop multiplies dt by `timescale` (e.g. 0.15),
 * so the whole world slows for `duration` seconds of *real* time.
 *
 * Usage:
 *   const hitStop = new HitStop();
 *   hitStop.trigger(0.06, 0.15);   // 60ms of real time at 15% speed
 *   const dt = hitStop.scale(rawDt); // pass through the engine loop
 */
export default class HitStop {
  constructor() {
    this.remaining = 0; // real seconds left
    this.timescale = 1;
  }

  trigger(duration, timescale) {
    // Stronger (lower) timescale wins if overlapping.
    if (duration > this.remaining || timescale < this.timescale) {
      this.remaining = Math.max(this.remaining, duration);
      this.timescale = Math.min(this.timescale, timescale);
    }
  }

  get active() {
    return this.remaining > 0;
  }

  /** Returns the effective dt for this frame. */
  scale(rawDt) {
    if (this.remaining <= 0) return rawDt;
    this.remaining -= rawDt;
    if (this.remaining <= 0) {
      this.remaining = 0;
      this.timescale = 1;
      return rawDt;
    }
    return rawDt * this.timescale;
  }
}

